export const places={
 clinic:{name:'The clinic',person:'Dr. Sade',role:'Clinic operator',need:3,copy:'“There are vaccines in that fridge. People can argue about fairness tomorrow. Tonight, keep this place running.”',context:'The clinic needs 3 power units. Anything less means moving patients and losing the cold chain.',actions:['promise']},
 market:{name:'The market',person:'Bisi',role:'Market association chair',need:3,copy:'“You want us to close early again? Some people have not sold anything since morning.”',context:'The market needs 3 units. A compensated early closing agreement can reduce that to 2.',actions:['negotiate','gift']},
 homes:{name:'The compounds',person:'Musa',role:'Residents’ organiser',need:2,copy:'“We voted for somebody who would listen. Go and tell them that these houses have people inside.”',context:'The compounds need 2 units for water pumps and shared lighting. Musa can help you explain a difficult decision.',actions:['listen']},
 council:{name:'The council hall',person:'Chief Dairo',role:'Council chair',need:1,copy:'“There is an important reception tonight. Keep the hall on and we will remember who helped us.”',context:'The hall requests 1 unit. Dairo has influence, but the substation records may tell a different story.',actions:['recover']},
 station:{name:'The substation',person:'Teni',role:'Electrical technician',copy:'“The feeder is damaged. Give me materials and twenty minutes. And somebody should check that extra cable.”',context:'Current supply: 6 units. Repairing the feeder restores 2. The maintenance record may explain another missing unit.',actions:['inspect','repair']},
 press:{name:'The press desk',person:'Dele',role:'Community reporter',copy:'“I can print what happened. But bring something I can verify. Everybody has a story; where are the records?”',context:'Publishing evidence earns public trust and exposes any private payment you accepted.',actions:['publish']}
};
export const actions={
 promise:{label:'Promise the clinic full power',minutes:10,cost:0,requires:()=>true,apply:s=>{s.trust++;s.promised=true;},log:'You promised Dr. Sade all 3 clinic units. She will remember whether you keep your word.'},
 negotiate:{label:'Fund an early closing agreement',minutes:10,cost:10000,requires:()=>true,apply:s=>{s.marketNeed=2;s.trust++;},log:'Bisi agreed to close part of the market early. Market demand falls to 2 units.'},
 gift:{label:'Accept Bisi’s private payment',minutes:10,cost:-20000,requires:s=>!s.published,blocked:'After publication, Bisi withdraws the offer. Your finances are under scrutiny.',apply:s=>{s.privatePayment=true;s.trust--;},log:'You accepted ₦20,000 off the record. Bisi expects the market to stay open.'},
 listen:{label:'Meet the residents',minutes:10,cost:0,requires:()=>true,apply:s=>{s.trust+=2;s.residents=true;},log:'Musa will help explain your decision. Residents feel they have been heard.'},
 inspect:{label:'Read the maintenance record',minutes:10,cost:0,requires:()=>true,apply:s=>{s.evidence=true;},log:'The record shows an unmetered council connection drawing 1 extra unit. You now have evidence.'},
 repair:{label:'Repair the damaged feeder',minutes:20,cost:30000,requires:()=>true,apply:s=>{s.supply+=2;},log:'Teni repaired the feeder. The neighbourhood now has 2 additional power units.'},
 recover:{label:'Challenge the council connection',minutes:10,cost:0,requires:s=>s.evidence,blocked:'You need evidence from the substation first.',apply:s=>{s.supply++;s.councilOpposed=true;},log:'Faced with the records, Dairo disconnected the extra cable. You recovered 1 unit and made a political opponent.'},
 publish:{label:'Publish the maintenance record',minutes:10,cost:0,requires:s=>s.evidence,blocked:'Dele needs the maintenance record before publishing.',apply:s=>{s.published=true;s.trust+=s.privatePayment?-2:2;},log:'Dele published the record. The shortage is now public knowledge, including any private payment you took.'}
};
export function initial(){return {version:1,started:false,finished:false,minutes:60,budget:40000,supply:6,trust:3,marketNeed:3,done:[],allocation:{clinic:0,market:0,homes:0,council:0},log:['You have one hour before nightfall. Six power units, nine requested. The final allocation is yours.']};}
export function demand(s,k){return k==='market'?s.marketNeed:places[k].need;}
export function availability(s,id){const a=actions[id];if(!a)return 'Unknown action.';if(s.finished)return 'The decision has already been announced.';if(s.done.includes(id))return 'Already completed.';if(s.minutes<a.minutes)return 'Not enough time before nightfall.';if(s.budget<a.cost)return 'Not enough community funds.';if(!a.requires(s))return a.blocked;return '';}
export function act(s,id){const error=availability(s,id);if(error)return {state:s,error};const next=structuredClone(s),a=actions[id];next.minutes-=a.minutes;next.budget-=a.cost;next.done.push(id);a.apply(next);next.log.unshift(a.log);for(const k of Object.keys(next.allocation))next.allocation[k]=Math.min(next.allocation[k],demand(next,k));return {state:next,error:''};}
export function allocated(s){return Object.values(s.allocation).reduce((a,b)=>a+b,0);}
export function allocate(s,key,delta){if(s.finished||!Object.hasOwn(s.allocation,key)||![-1,1].includes(delta))return s;const v=s.allocation[key]+delta;if(v<0||v>demand(s,key)||(delta>0&&allocated(s)>=s.supply))return s;const n=structuredClone(s);n.allocation[key]=v;return n;}
export function ending(s){const served=k=>s.allocation[k]>=demand(s,k);let trust=s.trust;for(const k of ['clinic','market','homes'])trust+=served(k)?1:-1;if(s.promised&&!served('clinic'))trust-=2;if(s.privatePayment&&s.published)trust-=2;const all=['clinic','market','homes'].every(served);let title=all?'The street stays on':served('clinic')?'A difficult night':'Nadabi goes dark';if(all&&s.privatePayment&&s.published)title='Light, with a scandal';return {title,trust:Math.max(0,Math.min(10,trust)),all,lines:[served('clinic')?'The clinic keeps its fridge and essential equipment running.':'Dr. Sade moves patients and loses the vaccine cold chain.',served('market')?(s.marketNeed===2?'The market honours the compensated early closing agreement.':'The market stays open through the evening.'):'Traders close stalls and lose the evening’s business.',served('homes')?'The compounds keep water pumps and shared lighting on.':'Residents queue for water in the dark.',served('council')?'Dairo’s reception goes ahead.':'Dairo cancels the reception and blames your decision.',s.councilOpposed?'You recovered power, but Dairo begins organising against you.':'The council’s hidden connection remains unchallenged.',s.privatePayment?(s.published?'The private payment is public. Residents question whose interests you served.':'You kept the payment secret. Bisi now has leverage over you.'):(s.published?'The public can see the maintenance records.':'The maintenance records remain outside public scrutiny.'),s.promised?(served('clinic')?'Dr. Sade remembers that you kept your promise.':'Dr. Sade remembers your broken promise.'):'You made no personal promise to Dr. Sade.']};}
export function restore(raw){try{const s=JSON.parse(raw),base=initial();if(s.version!==1||!Array.isArray(s.done)||!s.done.every(x=>Object.hasOwn(actions,x))||new Set(s.done).size!==s.done.length||!Array.isArray(s.log)||!s.log.every(x=>typeof x==='string'))return base;for(const k of ['minutes','budget','supply','trust','marketNeed'])if(!Number.isFinite(s[k]))return base;if(s.minutes<0||s.minutes>60||s.budget<0||s.budget>60000||s.supply<6||s.supply>9||![2,3].includes(s.marketNeed))return base;if(!s.allocation||Object.keys(base.allocation).some(k=>!Number.isInteger(s.allocation[k])||s.allocation[k]<0||s.allocation[k]>demand(s,k))||Object.keys(s.allocation).length!==4||allocated(s)>s.supply)return base;return {...base,...s};}catch{return initial();}}
